internal fun resultOf(result: JSONObject): String =
if (result.optBoolean("ok")) ControlAudit.RESULT_OK else ControlAudit.RESULT_FAILED
private fun fail(message: String, reason: String): JSONObject = JSONObject()
.put("__error", message)
.put("reason", reason)
}

