override fun onPageFinished(view: WebView, finishedUrl: String) {
if (tab.view !== view) return
// 同 onPageStarted：内置错误页的完成事件不得覆盖 error 态（其 URL 是 about:blank）。
if (tab.errorPageUrl != null && !finishedUrl.startsWith("http")) return
